def get_active_file(session_id, vault_id=None, include_content=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0189000" if __import__("os").path.isdir("./environment_mix/0189000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log(status, error_code=None):
        entry = {
            "id": f"obs_req_{int(time.time()*1000)}",
            "endpoint": "get_active_file",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(session_id, str) or not re.match(r"^obs_ses_[0-9A-Z]{18,}$", session_id or ""):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid session_id format.")
    if vault_id is not None:
        if not isinstance(vault_id, str) or not re.match(r"^obs_vlt_[0-9A-Z]{18,}$", vault_id or ""):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid vault_id format.")
    if include_content is not None and not isinstance(include_content, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_content must be a boolean when provided.")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    files = _load("files.json")
    if not isinstance(files, list):
        files = []
    vaults = _load("vaults.json")
    if not isinstance(vaults, list):
        vaults = []

    ses = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not ses:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Session not found.")

    if vault_id is not None and ses.get("vault_id") != vault_id:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Session not found in specified vault.")

    active_file_id = ses.get("active_file_id")
    if not active_file_id:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Session has no active file.")

    frow = next((f for f in files if isinstance(f, dict) and f.get("id") == active_file_id), None)
    if not frow:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Active file not found.")

    # must have status='available' and is_deleted=false
    if frow.get("status") != "available" or bool(frow.get("is_deleted")):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Active file is not available.")

    # Ensure file belongs to session's vault (and vault exists)
    if frow.get("vault_id") != ses.get("vault_id"):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Active file not found in session vault.")
    vrow = next((v for v in vaults if isinstance(v, dict) and v.get("id") == ses.get("vault_id")), None)
    if not vrow:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Vault not found for session.")

    # update last_seen_at
    ses["last_seen_at"] = now
    ses["updated_at"] = now
    _save("sessions.json", sessions)

    out_file = dict(frow)
    if not include_content:
        out_file["content"] = None

    _log("ok", None)
    return {
        "session": {
            "id": ses.get("id"),
            "vault_id": ses.get("vault_id"),
            "active_file_id": ses.get("active_file_id"),
            "status": ses.get("status"),
            "last_seen_at": ses.get("last_seen_at"),
            "updated_at": ses.get("updated_at"),
        },
        "file": out_file,
    }

def open_file(session_id, vault_id, file_id=None, path=None, create_if_missing=None, **_extra):
    import json, os, datetime, time, secrets, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0189000" if __import__("os").path.isdir("./environment_mix/0189000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "open_file"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mk_req_id():
        return f"obs_req_{secrets.token_hex(12).upper()}"

    def _log(status, error_code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": _now(),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.utcnow()
        window_s = 60
        limit = 300
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if (now_dt - dt).total_seconds() <= window_s:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Too many requests. Please retry later.", window_seconds=window_s, limit=limit)
            else:
                break
        return None

    def _sha256_text(s):
        if s is None:
            s = ""
        if not isinstance(s, str):
            s = str(s)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _mk_id(prefix):
        return f"{prefix}{secrets.token_hex(12).upper()}"

    def _find_by_id(rows, rid):
        for r in rows:
            if isinstance(r, dict) and r.get("id") == rid:
                return r
        return None

    def _validate_id(pat, val, field):
        if val is None:
            return None
        if not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string.")
        if not re.match(pat, val):
            return _err("VALIDATION_ERROR", f"{field} has invalid format.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    e = _validate_id(r"^obs_ses_[0-9A-Z]{18,}$", session_id, "session_id")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    e = _validate_id(r"^obs_vlt_[0-9A-Z]{18,}$", vault_id, "vault_id")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if file_id is None and path is None:
        e = _err("VALIDATION_ERROR", "Either file_id or path must be provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if file_id is not None:
        e = _validate_id(r"^obs_fil_[0-9A-Z]{18,}$", file_id, "file_id")
        if e:
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    if path is not None and (not isinstance(path, str) or path.strip() == ""):
        e = _err("VALIDATION_ERROR", "path must be a non-empty string when provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if create_if_missing is None:
        create_if_missing = False
    if not isinstance(create_if_missing, bool):
        e = _err("VALIDATION_ERROR", "create_if_missing must be a boolean when provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    vaults = _load("vaults.json")
    files = _load("files.json")
    sessions = _load("sessions.json")
    ops = _load("edit_operations.json")

    if not isinstance(vaults, list) or not isinstance(files, list) or not isinstance(sessions, list) or not isinstance(ops, list):
        e = _err("NOT_FOUND", "Datastore unavailable.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    vlt = _find_by_id(vaults, vault_id)
    if not vlt:
        e = _err("NOT_FOUND", "Vault not found.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    ses = _find_by_id(sessions, session_id)
    if not ses:
        e = _err("NOT_FOUND", "Session not found.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if ses.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Session is not active.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Session is bound to a vault; must match requested vault_id
    if ses.get("vault_id") != vault_id:
        e = _err("CONFLICT", "Session vault_id does not match requested vault_id.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    target_file = None
    if file_id is not None:
        target_file = _find_by_id(files, file_id)
        if not target_file or target_file.get("vault_id") != vault_id:
            e = _err("NOT_FOUND", "file_id not found in the specified vault.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    else:
        # Resolve by path
        for f in files:
            if isinstance(f, dict) and f.get("vault_id") == vault_id and f.get("path") == path:
                target_file = f
                break
        if not target_file and not create_if_missing:
            e = _err("NOT_FOUND", "path not found in the specified vault.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if not target_file and create_if_missing:
            # Creating a file is a mutation; respect vault status
            if vlt.get("status") in ("read_only", "disabled"):
                e = _err("INVALID_TRANSITION", f"Vault is {vlt.get('status')}; create_if_missing is not allowed.")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            # Build file metadata
            p = path.strip().lstrip("/")
            if p == "":
                e = _err("VALIDATION_ERROR", "path must be non-empty.")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            basename = p.split("/")[-1]
            dir_path = "/".join(p.split("/")[:-1])
            if "." in basename:
                ext = basename.split(".")[-1]
            else:
                ext = "md"
                basename = basename + ".md"
                p = (dir_path + "/" if dir_path else "") + basename
            # uniqueness constraint (vault_id, path)
            for f in files:
                if isinstance(f, dict) and f.get("vault_id") == vault_id and f.get("path") == p:
                    target_file = f
                    break
            if not target_file:
                now = _now()
                new_id = _mk_id("obs_fil_")
                target_file = {
                    "id": new_id,
                    "vault_id": vault_id,
                    "path": p,
                    "dir_path": dir_path,
                    "basename": basename,
                    "extension": ext,
                    "mime_type": "text/markdown" if ext.lower() == "md" else None,
                    "content": "",
                    "content_sha256": _sha256_text(""),
                    "size_bytes": 0,
                    "is_deleted": False,
                    "status": "available",
                    "last_opened_at": None,
                    "created_at": now,
                    "updated_at": now,
                }
                files.append(target_file)
                _save("files.json", files)

    # Cannot open deleted files as active
    if target_file.get("status") == "deleted" or target_file.get("is_deleted") is True:
        e = _err("NOT_FOUND", "File is deleted and cannot be opened.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Update session active_file_id
    ses["active_file_id"] = target_file.get("id")
    ses["last_seen_at"] = _now()
    ses["updated_at"] = _now()
    target_file["last_opened_at"] = _now()
    target_file["updated_at"] = _now()

    # Record edit operation open_file (applied)
    op_id = _mk_id("obs_op_")
    op_now = _now()
    op_row = {
        "id": op_id,
        "vault_id": vault_id,
        "file_id": target_file.get("id"),
        "session_id": session_id,
        "operation_type": "open_file",
        "target_selector": None,
        "payload_text": None,
        "before_sha256": target_file.get("content_sha256"),
        "after_sha256": target_file.get("content_sha256"),
        "status": "applied",
        "error_message": None,
        "created_at": op_now,
        "updated_at": op_now,
    }
    ops.append(op_row)

    _save("sessions.json", sessions)
    _save("files.json", files)
    _save("edit_operations.json", ops)

    resp = {
        "session_id": session_id,
        "vault_id": vault_id,
        "active_file_id": ses.get("active_file_id"),
        "file": target_file,
        "operation": op_row,
    }
    _log("ok", meta={"operation_id": op_id, "file_id": target_file.get("id")})
    return resp

def insert_file(vault_id, selector, text, file_id=None, path=None, session_id=None, expected_sha256=None, **_extra):
    import json, os, datetime, hashlib, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0189000" if __import__("os").path.isdir("./environment_mix/0189000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "insert_file"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mk_req_id():
        return f"obs_req_{secrets.token_hex(12).upper()}"

    def _log(status, error_code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _mk_req_id(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": _now(),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.utcnow()
        window_s = 60
        limit = 300
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if (now_dt - dt).total_seconds() <= window_s:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Too many requests. Please retry later.", window_seconds=window_s, limit=limit)
            else:
                break
        return None

    def _sha256_text(s):
        if s is None:
            s = ""
        if not isinstance(s, str):
            s = str(s)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _mk_id(prefix):
        return f"{prefix}{secrets.token_hex(12).upper()}"

    def _find_by_id(rows, rid):
        for r in rows:
            if isinstance(r, dict) and r.get("id") == rid:
                return r
        return None

    def _validate_id(pat, val, field):
        if val is None:
            return None
        if not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string.")
        if not re.match(pat, val):
            return _err("VALIDATION_ERROR", f"{field} has invalid format.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    e = _validate_id(r"^obs_vlt_[0-9A-Z]{18,}$", vault_id, "vault_id")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if file_id is None and path is None:
        e = _err("VALIDATION_ERROR", "Either file_id or path must be provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if file_id is not None:
        e = _validate_id(r"^obs_fil_[0-9A-Z]{18,}$", file_id, "file_id")
        if e:
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    if session_id is not None:
        e = _validate_id(r"^obs_ses_[0-9A-Z]{18,}$", session_id, "session_id")
        if e:
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    if expected_sha256 is not None and not isinstance(expected_sha256, str):
        e = _err("VALIDATION_ERROR", "expected_sha256 must be a string when provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(selector, dict):
        e = _err("VALIDATION_ERROR", "selector must be an object.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if set(selector.keys()) - {"type", "value", "position"}:
        e = _err("VALIDATION_ERROR", "selector has unknown fields.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    stype = selector.get("type")
    sval = selector.get("value")
    spos = selector.get("position")
    if stype not in ("heading", "block", "frontmatter"):
        e = _err("VALIDATION_ERROR", "selector.type must be one of: heading, block, frontmatter.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if spos not in ("before", "after", "replace"):
        e = _err("VALIDATION_ERROR", "selector.position must be one of: before, after, replace.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(sval, str) or sval == "":
        e = _err("VALIDATION_ERROR", "selector.value must be a non-empty string.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(text, str):
        e = _err("VALIDATION_ERROR", "text must be a string.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    payload_too_big = len(text) > 200000

    vaults = _load("vaults.json")
    files = _load("files.json")
    sessions = _load("sessions.json")
    ops = _load("edit_operations.json")

    if not isinstance(vaults, list) or not isinstance(files, list) or not isinstance(sessions, list) or not isinstance(ops, list):
        e = _err("NOT_FOUND", "Datastore unavailable.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    vlt = _find_by_id(vaults, vault_id)
    if not vlt:
        e = _err("NOT_FOUND", "Vault not found.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if vlt.get("status") in ("read_only", "disabled"):
        e = _err("INVALID_TRANSITION", f"Vault is {vlt.get('status')}; mutating operations are not allowed.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    ses = None
    if session_id is not None:
        ses = _find_by_id(sessions, session_id)
        if not ses:
            e = _err("NOT_FOUND", "Session not found.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if ses.get("status") != "active":
            e = _err("INVALID_TRANSITION", "Session is not active.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        # Must enforce file belongs to same vault as session context
        if ses.get("vault_id") != vault_id:
            e = _err("CONFLICT", "session_id vault_id does not match provided vault_id.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    fil = None
    if file_id is not None:
        fil = _find_by_id(files, file_id)
        if not fil or fil.get("vault_id") != vault_id:
            e = _err("NOT_FOUND", "file_id not found in the specified vault.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    else:
        if not isinstance(path, str) or path.strip() == "":
            e = _err("VALIDATION_ERROR", "path must be a non-empty string when provided.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        for f in files:
            if isinstance(f, dict) and f.get("vault_id") == vault_id and f.get("path") == path:
                fil = f
                break
        if not fil:
            e = _err("NOT_FOUND", "path not found in the specified vault.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    if fil.get("status") == "deleted" or fil.get("is_deleted") is True:
        e = _err("NOT_FOUND", "File is deleted and cannot be modified.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    op_id = _mk_id("obs_op_")
    now = _now()
    op_row = {
        "id": op_id,
        "vault_id": vault_id,
        "file_id": fil.get("id"),
        "session_id": session_id,
        "operation_type": "insert",
        "target_selector": selector,
        "payload_text": text,
        "before_sha256": fil.get("content_sha256"),
        "after_sha256": None,
        "status": "queued",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    if payload_too_big:
        op_row["status"] = "failed"
        op_row["error_message"] = "payload_text exceeds quota: 200000 character limit."
        op_row["updated_at"] = _now()
        ops.append(op_row)
        _save("edit_operations.json", ops)
        e = _err("QUOTA_EXCEEDED", op_row["error_message"])
        _log("error", e["error"]["code"], e["error"]["message"], meta={"operation_id": op_id})
        return e

    if expected_sha256 is not None and fil.get("content_sha256") != expected_sha256:
        fil["status"] = "conflict"
        fil["updated_at"] = _now()
        op_row["status"] = "failed"
        op_row["error_message"] = "Content hash mismatch (optimistic concurrency failure)."
        op_row["updated_at"] = _now()
        ops.append(op_row)
        _save("files.json", files)
        _save("edit_operations.json", ops)
        e = _err("CONFLICT", op_row["error_message"])
        _log("error", e["error"]["code"], e["error"]["message"], meta={"operation_id": op_id})
        return e

    content = fil.get("content")
    if content is None:
        op_row["status"] = "failed"
        op_row["error_message"] = "File content is not available for editing."
        op_row["updated_at"] = _now()
        ops.append(op_row)
        _save("edit_operations.json", ops)
        e = _err("CONFLICT", op_row["error_message"])
        _log("error", e["error"]["code"], e["error"]["message"], meta={"operation_id": op_id})
        return e
    if not isinstance(content, str):
        content = str(content)

    def _apply_heading(c, heading_text, position, insert_text):
        lines = c.splitlines(keepends=True)
        matches = []
        for idx, ln in enumerate(lines):
            m = re.match(r"^(#{1,6})\s+(.*?)(\s*)$", ln.rstrip("\n"))
            if not m:
                continue
            ht = m.group(2).strip()
            if ht.lower() == heading_text.strip().lower():
                matches.append(idx)
        if len(matches) != 1:
            return None, f"Selector did not resolve uniquely: heading '{heading_text}' matched {len(matches)} sections."
        i = matches[0]
        level = len(re.match(r"^(#{1,6})", lines[i]).group(1))
        j = i + 1
        while j < len(lines):
            m2 = re.match(r"^(#{1,6})\s+", lines[j])
            if m2 and len(m2.group(1)) <= level:
                break
            j += 1
        if position == "before":
            new_lines = lines[:i] + [insert_text] + lines[i:]
        elif position == "after":
            new_lines = lines[:j] + [insert_text] + lines[j:]
        else:
            new_lines = lines[:i] + [insert_text] + lines[j:]
        return "".join(new_lines), None

    def _apply_block(c, block_id, position, insert_text):
        pat = re.compile(r"\^" + re.escape(block_id.strip()) + r"\b")
        lines = c.splitlines(keepends=True)
        matches = []
        for idx, ln in enumerate(lines):
            if pat.search(ln):
                matches.append(idx)
        if len(matches) != 1:
            return None, f"Selector did not resolve uniquely: block '{block_id}' matched {len(matches)} blocks."
        i = matches[0]
        if position == "before":
            new_lines = lines[:i] + [insert_text] + lines[i:]
        elif position == "after":
            new_lines = lines[:i+1] + [insert_text] + lines[i+1:]
        else:
            new_lines = lines[:i] + [insert_text] + lines[i+1:]
        return "".join(new_lines), None

    def _parse_frontmatter(c):
        if not c.startswith("---"):
            return None, None, None, "No frontmatter found."
        lines = c.splitlines(keepends=True)
        if not lines or lines[0].strip() != "---":
            return None, None, None, "No frontmatter found."
        end_idx = None
        for i in range(1, len(lines)):
            if lines[i].strip() == "---":
                end_idx = i
                break
        if end_idx is None:
            return None, None, None, "Frontmatter delimiter not closed."
        fm_lines = lines[1:end_idx]
        fm = {}
        for ln in fm_lines:
            s = ln.rstrip("\n")
            if not s.strip():
                continue
            if ":" not in s:
                return None, None, None, "Frontmatter is not parseable as simple key: value pairs."
            k, v = s.split(":", 1)
            fm[k.strip()] = v.lstrip()
        return 0, end_idx + 1, fm, None

    def _apply_frontmatter(c, key, position, insert_text):
        fm_start, fm_end, fm, perr = _parse_frontmatter(c)
        if perr:
            return None, f"Selector did not resolve uniquely: frontmatter '{key}' not found."
        if key not in fm:
            return None, f"Selector did not resolve uniquely: frontmatter '{key}' not found."
        lines = c.splitlines(keepends=True)
        key_line_idx = None
        for i in range(1, fm_end - 1):
            s = lines[i].rstrip("\n")
            if ":" in s:
                k = s.split(":", 1)[0].strip()
                if k == key:
                    key_line_idx = i
                    break
        if key_line_idx is None:
            return None, f"Selector did not resolve uniquely: frontmatter '{key}' not found."
        if position == "before":
            new_lines = lines[:key_line_idx] + [insert_text] + lines[key_line_idx:]
        elif position == "after":
            new_lines = lines[:key_line_idx+1] + [insert_text] + lines[key_line_idx+1:]
        else:
            if "\n" in insert_text:
                return None, "Frontmatter replace requires single-line text."
            prefix = lines[key_line_idx].split(":", 1)[0]
            new_lines = lines[:key_line_idx] + [f"{prefix}: {insert_text}\n"] + lines[key_line_idx+1:]
        return "".join(new_lines), None

    new_content = None
    sel_err = None
    if stype == "heading":
        new_content, sel_err = _apply_heading(content, sval, spos, text)
    elif stype == "block":
        new_content, sel_err = _apply_block(content, sval, spos, text)
    else:
        new_content, sel_err = _apply_frontmatter(content, sval, spos, text)

    if sel_err is not None:
        op_row["status"] = "failed"
        op_row["error_message"] = sel_err
        op_row["updated_at"] = _now()
        ops.append(op_row)
        _save("edit_operations.json", ops)
        e = _err("CONFLICT", sel_err)
        _log("error", e["error"]["code"], e["error"]["message"], meta={"operation_id": op_id})
        return e

    fil["content"] = new_content
    fil["content_sha256"] = _sha256_text(new_content)
    fil["size_bytes"] = len(new_content.encode("utf-8"))
    fil["updated_at"] = _now()
    if fil.get("status") == "conflict":
        fil["status"] = "available"
        fil["is_deleted"] = False

    op_row["status"] = "applied"
    op_row["after_sha256"] = fil["content_sha256"]
    op_row["updated_at"] = _now()
    ops.append(op_row)

    if ses is not None:
        ses["last_seen_at"] = _now()
        ses["updated_at"] = _now()
        _save("sessions.json", sessions)

    _save("files.json", files)
    _save("edit_operations.json", ops)

    resp = {
        "vault_id": vault_id,
        "file": fil,
        "operation": op_row,
    }
    _log("ok", meta={"operation_id": op_id, "file_id": fil.get("id")})
    return resp

def search_simple(vault_id, query, session_id=None, dir_path=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, secrets, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0189000" if __import__("os").path.isdir("./environment_mix/0189000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_simple"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"obs_req_{secrets.token_hex(12).upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": _now(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_s = 60
        limit_req = 300
        cnt = 0
        for r in reversed(logs[-2000:]):
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if (now - dt).total_seconds() <= window_s:
                cnt += 1
        if cnt >= limit_req:
            return _err("RATE_LIMIT", "Too many requests. Please retry later.", window_seconds=window_s, limit=limit_req)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", error_code=rl["error"]["code"], message=rl["error"]["message"])
        return rl

    # Validate
    if not isinstance(vault_id, str) or not re.match(r"^obs_vlt_[0-9A-Z]{18,}$", vault_id):
        e = _err("VALIDATION_ERROR", "Invalid vault_id format.")
        _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e
    if session_id is not None and (not isinstance(session_id, str) or not re.match(r"^obs_ses_[0-9A-Z]{18,}$", session_id)):
        e = _err("VALIDATION_ERROR", "Invalid session_id format.")
        _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e
    if not isinstance(query, str):
        e = _err("VALIDATION_ERROR", "query must be a string.")
        _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e
    if len(query) < 1 or len(query) > 4096:
        e = _err("VALIDATION_ERROR", "query length must be between 1 and 4096.")
        _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e
    if dir_path is not None and not isinstance(dir_path, str):
        e = _err("VALIDATION_ERROR", "dir_path must be a string when provided.")
        _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
        _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.")
        _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e

    vaults = _load("vaults.json")
    if not isinstance(vaults, list):
        vaults = []
    vault = next((v for v in vaults if v.get("id") == vault_id), None)
    if not vault:
        e = _err("NOT_FOUND", "Vault not found.")
        _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    if session_id is not None:
        ses = next((s for s in sessions if s.get("id") == session_id), None)
        if not ses:
            e = _err("NOT_FOUND", "Session not found.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e
        if ses.get("vault_id") != vault_id:
            e = _err("CONFLICT", "Session vault_id does not match requested vault_id.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e

    files = _load("files.json")
    if not isinstance(files, list):
        files = []

    def _norm_dir(p):
        if p is None:
            return None
        p = p.strip()
        if p == "" or p == "/":
            return ""
        return p.strip("/")

    scope = _norm_dir(dir_path)

    # dir_path existence check (business rule)
    if scope is not None:
        # Consider exists if any file has dir_path == scope or startswith scope + '/'
        exists = False
        for f in files:
            if f.get("vault_id") != vault_id:
                continue
            dp = f.get("dir_path")
            if dp == scope or (isinstance(dp, str) and scope != "" and dp.startswith(scope + "/")):
                exists = True
                break
            if scope == "" and f.get("vault_id") == vault_id:
                exists = True
                break
        if not exists:
            e = _err("NOT_FOUND", "dir_path does not exist within the vault.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e

    # Pagination cursor: base64 of "offset:<n>"
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e
        if not raw.startswith("offset:"):
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e
        try:
            offset = int(raw.split(":", 1)[1])
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e
        if offset < 0:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e

    # Create search_query row (always creates a new query as per business rules)
    sqs = _load("search_queries.json")
    if not isinstance(sqs, list):
        sqs = []
    srs = _load("search_results.json")
    if not isinstance(srs, list):
        srs = []

    now = _now()
    sq_id = f"obs_srch_{secrets.token_hex(10).upper()}"
    sq_row = {
        "id": sq_id,
        "vault_id": vault_id,
        "session_id": session_id,
        "query_text": query,
        "dir_path": scope,
        "status": "queued",
        "result_count": 0,
        "created_at": now,
        "updated_at": now
    }
    sqs.append(sq_row)
    _save("search_queries.json", sqs)

    # Compute matches: status='available' and content not null
    q = query.lower()
    matches = []
    for f in files:
        if f.get("vault_id") != vault_id:
            continue
        if f.get("status") != "available":
            continue
        if f.get("content") is None:
            continue
        if scope is not None:
            dp = f.get("dir_path") or ""
            if scope == "":
                pass
            else:
                if not (dp == scope or (isinstance(dp, str) and dp.startswith(scope + "/"))):
                    continue
        content = f.get("content") or ""
        idx = content.lower().find(q)
        if idx == -1:
            continue
        # snippet: 40 chars around match
        start = max(0, idx - 40)
        end = min(len(content), idx + len(query) + 40)
        snippet = content[start:end]
        score = float(len(query)) / max(1.0, float(len(content))) * 1000.0
        matches.append((score, f.get("updated_at") or "", f.get("path") or "", f.get("id"), snippet))

    # Order by score desc then updated_at desc then path asc
    matches.sort(key=lambda x: (-x[0], x[1], x[2]))

    # Write ordered search_results rows for all matches (not just page)
    created = 0
    rank = 1
    for score, _upd, _path, fid, snippet in matches:
        # unique(search_query_id, rank) and unique(search_query_id, file_id)
        srs.append({
            "id": f"obs_sres_{secrets.token_hex(10).upper()}",
            "search_query_id": sq_id,
            "file_id": fid,
            "rank": rank,
            "score": score if score >= 0 else 0.0,
            "snippet": snippet,
            "created_at": now,
            "updated_at": now
        })
        rank += 1
        created += 1
    _save("search_results.json", srs)

    # Mark search_query completed
    sq_row["status"] = "completed"
    sq_row["result_count"] = created
    sq_row["updated_at"] = _now()
    _save("search_queries.json", sqs)

    # Page results
    total = len(matches)
    page = matches[offset:offset + limit]
    items = []
    for i, (score, _upd, _path, fid, snippet) in enumerate(page, start=offset + 1):
        f = next((x for x in files if x.get("id") == fid), None)
        if not f:
            continue
        items.append({
            "rank": i,
            "score": score,
            "snippet": snippet,
            "file": {k: f.get(k) for k in [
                "id", "vault_id", "path", "dir_path", "basename", "extension",
                "mime_type", "size_bytes", "status", "is_deleted",
                "last_opened_at", "created_at", "updated_at", "content_sha256"
            ]}
        })

    next_offset = offset + limit
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "vault_id": vault_id,
        "search_query_id": sq_id,
        "query": query,
        "dir_path": scope,
        "results": items,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
            "offset": offset
        }
    }
    _log("ok", meta={"vault_id": vault_id, "search_query_id": sq_id, "total": total})
    return resp

