            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e
        try:
            offset = int(raw.split(":", 1)[1])
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e
        if offset < 0:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("error", error_code=e["error"]["code"], message=e["error"]["message"])
            return e

    # Filter per business rules
    filtered = []
    for f in files:
        if f.get("vault_id") != vault_id:
            continue
        if not include_deleted and f.get("status") == "deleted":
            continue
        dp = f.get("dir_path") or ""
        if scope == "":
            in_scope = True
        else:
            if recursive:
                in_scope = (dp == scope) or (isinstance(dp, str) and dp.startswith(scope + "/"))
            else:
                in_scope = (dp == scope)
        if not in_scope:
            continue
        filtered.append(f)

    def _key(v):
        x = v.get(sort)
        # normalize None
        if x is None:
            return ""
        return x

    reverse = (order == "desc")
    if sort == "path":
        filtered.sort(key=lambda f: (f.get("path") or ""), reverse=reverse)
    else:
        # secondary stable sort by path
        filtered.sort(key=lambda f: (f.get("path") or ""))
        filtered.sort(key=lambda f: _key(f), reverse=reverse)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    items = []
    for f in page:
        items.append({k: f.get(k) for k in [
            "id", "vault_id", "path", "dir_path", "basename", "extension",
            "mime_type", "size_bytes", "status", "is_deleted",
            "last_opened_at", "created_at", "updated_at", "content_sha256"
        ]})

    next_offset = offset + limit
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "vault_id": vault_id,
        "dir_path": scope,
        "recursive": recursive,
        "include_deleted": include_deleted,
        "files": items,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
            "offset": offset
        },
        "sort": {"field": sort, "order": order}
    }
    _log("ok", meta={"vault_id": vault_id, "total": total, "returned": len(items)})
    return resp

def list_vaults(status=None, name_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0189000" if __import__("os").path.isdir("./environment_mix/0189000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Basic validation ---
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "read_only", "disabled"):
            return _err("VALIDATION_ERROR", "status must be one of: active, read_only, disabled")
    if name_prefix is not None and not isinstance(name_prefix, str):
        return _err("VALIDATION_ERROR", "name_prefix must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # --- Authorization: ambient. Deny only if store has an explicit access-control scheme and none matches. ---
    # This schema provides no caller identity / ACL collections. Therefore, treat caller as authorized.
    # (Never refuse well-formed requests due to missing explicit auth parameters.)

    # --- Cursor handling ---
    start = 0
    if cursor:
        # Opaque cursor: base64url of {"start": int, "v": 1}
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("start"), int) or obj["start"] < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid")
            start = obj["start"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "cursor is invalid")

    vaults = _load("vaults.json")
    if not isinstance(vaults, list):
        vaults = []

    # --- Filter/sort ---
    items = []
    np = name_prefix.lower() if isinstance(name_prefix, str) else None
    for v in vaults:
        if not isinstance(v, dict):
            continue
        if status is not None and v.get("status") != status:
            continue
        if np is not None:
            nm = v.get("name")
            if not isinstance(nm, str) or not nm.lower().startswith(np):
                continue
        items.append(v)

    # Deterministic ordering: by name (casefold), then id
    def _k(v):
        n = v.get("name")
        if not isinstance(n, str):
            n = ""
        i = v.get("id")
        if not isinstance(i, str):
            i = ""
        return (n.casefold(), i)

    items.sort(key=_k)

    total = len(items)
    page = items[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        tok = {"v": 1, "start": start + limit}
        enc = base64.urlsafe_b64encode(json.dumps(tok, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    latency_ms = int((time.time() - t0) * 1000)

    # Observable dynamics: schema has no request log collection; no counters to advance.

    return {
        "vaults": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
        },
        "meta": {
            "timestamp": now,
            "latency_ms": latency_ms,
        },
    }

def create_session(vault_id, client_name, **_extra):
    import json, os, datetime, time, re, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0189000" if __import__("os").path.isdir("./environment_mix/0189000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # --- Validate inputs ---
    if not isinstance(vault_id, str):
        return _err("VALIDATION_ERROR", "vault_id must be a string")
    if not re.match(r"^obs_vlt_[0-9A-Z]{18,}$", vault_id):
        return _err("VALIDATION_ERROR", "vault_id is malformed")
    if not isinstance(client_name, str):
        return _err("VALIDATION_ERROR", "client_name must be a string")
    if len(client_name) < 1 or len(client_name) > 200:
        return _err("VALIDATION_ERROR", "client_name length must be between 1 and 200 characters")

    vaults = _load("vaults.json")
    if not isinstance(vaults, list):
        vaults = []
    vrow = None
    for v in vaults:
        if isinstance(v, dict) and v.get("id") == vault_id:
            vrow = v
            break
    if vrow is None:
        return _err("NOT_FOUND", "vault not found", vault_id=vault_id)

    # FORBIDDEN in prompt, but contract's allowed codes do not include FORBIDDEN; use UNAUTHORIZED.
    if vrow.get("status") == "disabled":
        return _err("UNAUTHORIZED", "vault is disabled", vault_id=vault_id)

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # --- ID generation ---
    # Convention: obs_ses_ + 20 chars base36/uppercase (>=18). Ensure uniqueness within file.
    def _gen_id():
        alphabet = string.digits + string.ascii_uppercase
        return "obs_ses_" + "".join(random.choice(alphabet) for _ in range(20))

    existing_ids = {s.get("id") for s in sessions if isinstance(s, dict)}
    sid = _gen_id()
    tries = 0
    while sid in existing_ids and tries < 20:
        sid = _gen_id()
        tries += 1
    if sid in existing_ids:
        return _err("CONFLICT", "could not allocate unique session id")

    srow = {
        "id": sid,
        "vault_id": vault_id,
        "active_file_id": None,
        "client_name": client_name,
        "status": "active",
        "last_seen_at": now,
        "created_at": now,
        "updated_at": now,
    }

    sessions.append(srow)
    _save("sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "session": srow,
        "meta": {
            "timestamp": now,
            "latency_ms": latency_ms,
        },
    }

def get_file(file_id, include_content=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0189000" if __import__("os").path.isdir("./environment_mix/0189000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Validate inputs ---
    if not isinstance(file_id, str):
        return _err("VALIDATION_ERROR", "file_id must be a string")
    if not re.match(r"^obs_fil_[0-9A-Z]{18,}$", file_id):
        return _err("VALIDATION_ERROR", "file_id is malformed")
    if include_content is None:
        include_content = False
    if not isinstance(include_content, bool):
        return _err("VALIDATION_ERROR", "include_content must be a boolean")

    files = _load("files.json")
    if not isinstance(files, list):
        files = []
    frow = None
    for f in files:
        if isinstance(f, dict) and f.get("id") == file_id:
            frow = f
            break
    if frow is None:
        return _err("NOT_FOUND", "file not found", file_id=file_id)

    # Deleted files are not retrievable
    if frow.get("status") == "deleted" or frow.get("is_deleted") is True:
        return _err("NOT_FOUND", "file is deleted", file_id=file_id)

    # Vault must exist and be accessible; no ACLs exist in schema -> allow if vault exists.
    vault_id = frow.get("vault_id")
    vaults = _load("vaults.json")
    if not isinstance(vaults, list):
        vaults = []
    vrow = None
    for v in vaults:
        if isinstance(v, dict) and v.get("id") == vault_id:
            vrow = v
            break
    if vrow is None:
        return _err("NOT_FOUND", "vault not found for file", vault_id=vault_id, file_id=file_id)
    # Prompt says FORBIDDEN if cannot access vault; with no ACL, treat as accessible even if vault disabled.
    # (Disabled vault can still have metadata reads; only mutations are blocked by rules.)
    # If you want to hide disabled vault data, that would require an auth/ACL model not present here.

    # --- Update last_opened_at as observable state change for reads that "open" content snapshot ---
    # This endpoint is a fetch; still sets last_opened_at when include_content=True (closest proxy to "opened via API").
    mutated = False
    if include_content:
        frow["last_opened_at"] = now
        frow["updated_at"] = frow.get("updated_at") or now
        mutated = True

    if mutated:
        # Persist change
        for i, f in enumerate(files):
            if isinstance(f, dict) and f.get("id") == file_id:
                files[i] = frow
                break
        _save("files.json", files)

    # Shape response; omit content unless requested
    out = dict(frow)
    if not include_content:
        out["content"] = None

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "file": out,
        "meta": {
            "timestamp": now,
            "latency_ms": latency_ms,
            "include_content": include_content,
        },
    }
